<?php
if(!defined('ABSPATH')){exit;}
if(!defined('WP_CLI')||!WP_CLI){return;}

final class Orion_Manager_Queue_CLI_Command{
 /** Show queue and response counts. */
 public function stats(array $args,array $assoc_args):void{$queue=new Orion_Manager_Handoff();$rows=array();foreach($queue->counts()as$status=>$total)$rows[]=array('group'=>'queue','status'=>$status,'count'=>$total);foreach($queue->response_counts()as$status=>$total)$rows[]=array('group'=>'response','status'=>$status,'count'=>$total);WP_CLI\Utils\format_items($this->format($assoc_args),$rows,array('group','status','count'));}
 /**
  * List queue items without private text by default. Pass --details to include the customer question.
  *
  * @subcommand list
  */
 public function list_items(array $args,array $assoc_args):void{$filters=array();$status=sanitize_key((string)($assoc_args['status']??''));$priority=sanitize_key((string)($assoc_args['priority']??''));if($status!==''&&!Orion_Manager_Queue_Policy::is_status($status))WP_CLI::error('Unknown status.');if($priority!==''&&!in_array($priority,Orion_Manager_Queue_Policy::priorities(),true))WP_CLI::error('Unknown priority.');if($status!=='')$filters['status']=$status;if($priority!=='')$filters['priority']=$priority;$limit=max(1,min(200,absint($assoc_args['limit']??50)));$items=(new Orion_Manager_Handoff())->all($limit,$filters);$rows=array();foreach($items as$item){$row=array('id'=>(int)$item['id'],'status'=>(string)$item['status'],'priority'=>(string)$item['priority'],'reason_code'=>(string)$item['reason_code'],'assigned_user_id'=>(int)($item['assigned_user_id']??0),'response_status'=>(string)($item['response_status']??'none'),'trace_id'=>(int)($item['trace_id']??0),'created_at'=>(string)$item['created_at']);if(!empty($assoc_args['details']))$row['question']=(string)$item['question'];$rows[]=$row;}$fields=array('id','status','priority','reason_code','assigned_user_id','response_status','trace_id','created_at');if(!empty($assoc_args['details']))$fields[]='question';WP_CLI\Utils\format_items($this->format($assoc_args),$rows,$fields);}
 /** Show one queue item. Private text and diagnostic context require --details. */
 public function show(array $args,array $assoc_args):void{$id=absint($args[0]??0);if(!$id)WP_CLI::error('Provide a queue item ID.');$queue=new Orion_Manager_Handoff();$item=$queue->get($id);if(!$item)WP_CLI::error('Queue item #'.$id.' does not exist.');$summary=array('id'=>(int)$item['id'],'conversation_id'=>(int)$item['conversation_id'],'trace_id'=>(int)($item['trace_id']??0),'status'=>(string)$item['status'],'priority'=>(string)$item['priority'],'reason_code'=>(string)$item['reason_code'],'assigned_user_id'=>(int)($item['assigned_user_id']??0),'response_status'=>(string)($item['response_status']??'none'),'created_at'=>(string)$item['created_at'],'updated_at'=>(string)$item['updated_at'],'resolved_at'=>$item['resolved_at']??null,'response_approved_at'=>$item['response_approved_at']??null,'response_delivered_at'=>$item['response_delivered_at']??null,'history'=>$queue->history($id,50));if(!empty($assoc_args['details'])){$summary['question']=(string)$item['question'];$summary['private_resolution_note']=(string)($item['resolution_note']??'');$summary['manager_response']=(string)($item['manager_response']??'');$context=json_decode((string)($item['context_json']??''),true);$summary['diagnostic_context']=is_array($context)?$context:array();}WP_CLI::log(wp_json_encode($summary,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));}
 private function format(array $assoc_args):string{$format=sanitize_key((string)($assoc_args['format']??'table'));return in_array($format,array('table','json','csv','yaml'),true)?$format:'table';}
}
WP_CLI::add_command('orion-ai queue','Orion_Manager_Queue_CLI_Command');
